      editarContaDto.perfil?.nome &&
      Object.prototype.hasOwnProperty.call(
        TipoPerfil,
        editarContaDto.perfil.nome,
      )
    ) {
      tipoPerfilEnum = (TipoPerfil as any)[
        editarContaDto.perfil.nome
      ] as TipoPerfil;
    }
    await this.validarCliente(editarContaDto.idCliente, tipoPerfilEnum ?? "");

    // Busca a conta persistida para comparação e verifica a necessidade de bloqueio de alteração.
    const contaPersistida =
