    Uuid.create(dto.idFluxo, "idFluxo");

    // Buscar fluxo
    const fluxoPersistidoDto = await this.fluxosRep.buscarFluxo(
      dto.idFluxo,
      dto.idCliente,
    );
    this.validarExistenciaFluxo(fluxoPersistidoDto);

    // Verificar se fluxo é arquivável
    const statusArquivaveis = [StatusFluxo.CANCELADO, StatusFluxo.FINALIZADO];
    if (
      !statusArquivaveis.includes(
        StatusFluxo[fluxoPersistidoDto.dadosBasicos.status],
      )
    ) {
      throw new AppError(
        `O fluxo não pode ser ARQUIVADO pois se encontra com status ${fluxoPersistidoDto.dadosBasicos.status}`,
        {
          code: ErrorCode.FLUXO_ACAO_NEGADA,
          isOperational: false,
          meta: {
            statusIni: fluxoPersistidoDto.dadosBasicos.status,
            statusFim: StatusFluxo.ARQUIVADO,
          },
        },
      );
    }

    const validarGrupo = true;
    const { requisitanteLogadoDto } = await this.validarRequisitanteLogado({
      validarGrupo,
      idRequisitanteLogado: dto.idProvocador,
      idCliente: fluxoPersistidoDto.dadosBasicos.idCliente,
      idGrupo: fluxoPersistidoDto.dadosBasicos.idGrupo,
    });

    const eventoDto: EventoDto = {
      idFluxo: dto.idFluxo,
      idProvocador: requisitanteLogadoDto.id,
      nomeProvocador: requisitanteLogadoDto.nome,
      papelProvocador: TipoPapel.REQUISITANTE,
      acao: StatusFluxo.ARQUIVADO,
      ip: clientInfo?.ip,
      formaAcesso: clientInfo?.formaAcesso,
      latitude: clientInfo?.coordenadas?.[0],
      longitude: clientInfo?.coordenadas?.[1],
    };

    // Arquivar
    const fluxoArquivado = await this.fluxosRep.atualizarStatusFluxo(eventoDto);

    // Expirar documentos
    fluxoArquivado.documentosExpirados = true;
    fluxoArquivado.documentos.map((doc) => {
      return (doc.uri = null);
    });

    // Atribui propriedade e nome do requisitante
    this.adicionarDetalhesDePropriedade(
      [fluxoArquivado],
      requisitanteLogadoDto,
    );

    return fluxoArquivado;
