// --- repository: FluxosRepositorio.buscarFluxo ---
{
    try {
      // 1. Buscar o fluxo principal
      const fluxo = await this.buscarFluxoPrincipal(id, idCliente);

      if (!fluxo) return undefined;

      // 2. Buscar dados relacionados em paralelo
      const [interessados, documentos, eventos] = await Promise.all([
        this.buscarInteressadosDoFluxo(fluxo.id),
        this.buscarDocumentosComSelos(fluxo.id),
        this.buscarEventosDoFluxo(fluxo.id),
      ]);

      // 3. Montar o DTO
      const fluxoComDocsEventos = {
        ...fluxo,
        interessados,
        documentos,
        eventos,
      };

      const fluxoCompleto = FluxoPersistenceMapper.fromModel(
        fluxoComDocsEventos as any,
      );
      fluxoCompleto.interessados = interessados;

      return fluxoCompleto;
    } catch (error) {
      console.error("Erro ao buscar fluxo:", error);
      throw new Error(
        "O Neosigner está com problemas técnicos. Tente mais tarde.",
      );
    }
  }
// --- repository: FluxosRepositorio.atualizarStatusFluxo ---
{
    // Garantir que acao é um valor válido do enum
    const acaoValida = Object.values(StatusFluxo).includes(
      eventoDto.acao as unknown as StatusFluxo,
    );
    if (!acaoValida) {
      throw new Error(`Status de fluxo inválido: ${eventoDto.acao}`);
    }

    let idFluxo: string;
    let idCliente: string;

    const affectedRows = await this.unitOfWork.executeInTransaction(
      async (transaction) => {
        const t = transaction.getNativeTransaction();

        const updateData: any = {
          status: eventoDto.acao,
        };

        if (
          [StatusFluxo.INICIADO, StatusFluxo.INICIANDO].includes(
            StatusFluxo[eventoDto.acao as keyof typeof StatusFluxo],
          )
        ) {
          updateData.initializedAt = new Date();
        }

        const [rows] = await FluxoModelo.update(updateData, {
          where: { id: eventoDto.idFluxo },
          transaction: t,
        });

        if (rows === 0) {
          return 0;
        }

        if (eventoDto.acao === StatusFluxo.INICIADO) {
          eventoDto.papelProvocador = TipoPerfil.REQUISITANTE;
        }

        await this.salvarEvento(eventoDto, t);

        const fluxo = await FluxoModelo.findByPk(eventoDto.idFluxo, {
          transaction: t,
        });

        if (!fluxo) {
          throw new Error("Fluxo desapareceu após atualização");
        }

        idFluxo = fluxo.id;
        idCliente = fluxo.idCliente;

        return rows;
      },
    );

    if (affectedRows === 0) {
      return undefined;
    }

    return this.buscarFluxo(idFluxo!, idCliente!);
  }

