// --- handler: MonitoracaoController.handle ---
{
    const nomeCliente =
      typeof request.query.nomeCliente === "string"
        ? request.query.nomeCliente
        : undefined;
    const siglaCliente =
      typeof request.query.siglaCliente === "string"
        ? request.query.siglaCliente
        : undefined;
    const data =
      typeof request.query.data === "string" ? request.query.data : undefined;

    const filtros: MonitoracaoInput = {
      nomeCliente,
      siglaCliente,
      data,
    };

    if (!this.roles.includes("ADMINISTRADOR")) {
      throw new AppError(
        "Usuário não autorizado ou não possui perfil ativo para esta funcionalidade.",
        {
          code: ErrorCode.USUARIO_NAO_AUTORIZADO,
          isOperational: false,
          meta: { user: { id: this.idConta } },
        },
      );
    }

    const resposta = await this.monitoracao.execute(filtros);

    return response.status(200).json(resposta);
  }
// --- use-case: Monitoracao.execute ---
{
    const bilhetagemQueue = RedisQueue.getInstance(BILHETAGEM_QUEUE_NAME);

    // Carrega os jobs atuais das DLQs usadas na monitoracao.
    const [finalizacaoDLQ, bilhetagemDLQ] = await Promise.all([
      this.finalizacaoDLQ.listarDLQJobs(),
      this.bilhetagemDLQ.listarDLQJobs(),
      bilhetagemQueue.getQueueLength(),
      bilhetagemQueue.getQueueLengthByName(BILHETAGEM_DLQ_NAME),
    ]);

    // Prepara cache de clientes por CNPJ para enriquecer os filtros por nome/sigla.
    const clientesPorCnpj = await this.buscarClientesPorCnpj([
      ...finalizacaoDLQ,
      ...bilhetagemDLQ,
    ]);

    // Aplica filtros de nome/sigla/data sobre os jobs encontrados nas filas.
    const finalizacaoFiltrada = finalizacaoDLQ.filter((job) =>
      this.aplicarFiltros(
        job as unknown as Record<string, unknown>,
        filtros,
        clientesPorCnpj,
      ),
    );
    const bilhetagemFiltrada = bilhetagemDLQ.filter((job) =>
      this.aplicarFiltros(
        job as unknown as Record<string, unknown>,
        filtros,
        clientesPorCnpj,
      ),
    );

    // Reduz o payload de retorno para uma allowlist de campos seguros.
    const finalizacaoSanitizada = finalizacaoFiltrada.map((job) =>
      this.sanitizarFinalizacaoJob(job as unknown as Record<string, unknown>),
    );
    const bilhetagemSanitizada = bilhetagemFiltrada.map((job) =>
      this.sanitizarBilhetagemJob(job as Record<string, unknown>),
    );

    // Consulta global, sem idCliente
    const fluxosCanceladosResults = await this.eventosRep.contarFluxosPorStatus(
      { data: filtros.data },
      "CANCELADO",
    );

    const fluxosFinalizadosResults =
      await this.eventosRep.contarFluxosPorStatus(
        { data: filtros.data },
        "FINALIZADO",
      );

    const fluxosCancelados = fluxosCanceladosResults.reduce(
      (sum, item) => sum + item.count,
      0,
    );

    const fluxosFinalizados = fluxosFinalizadosResults.reduce(
      (sum, item) => sum + item.count,
      0,
    );

    // So inclui bloco de fluxo encerrado quando ha dados relevantes para exibicao.
    const deveConstruirFluxosEncerrados =
      finalizacaoSanitizada.length > 0 ||
      bilhetagemSanitizada.length > 0 ||
      !!filtros.data;

    const dataNormalizada = filtros.data
      ? this.normalizarData(filtros.data)
      : undefined;

    // Retorna visao agregada (contadores) e detalhe das duas DLQs.
    return {
      ...(deveConstruirFluxosEncerrados && {
        fluxosEncerrados: {
          fluxosCancelados,
          fluxosFinalizados,
          ...(dataNormalizada && { data: dataNormalizada }),
          dataInicio: this.extrairDataMaisAntiga([
            ...finalizacaoSanitizada,
            ...bilhetagemSanitizada,
          ]),
        },
      }),
      finalizacaoFluxoDLQ: {
        numJobs: finalizacaoSanitizada.length,
        jobs: finalizacaoSanitizada,
      },
      bilhetagemDLQ: {
        numJobs: bilhetagemSanitizada.length,
        jobs: bilhetagemSanitizada,
      },
    };
  }

