/**
 * @swagger
 * /api/v1/clientes:
// --- handler: ListarClientesController.handle ---
{
    // Ler QueryParam e ajustar tipagem
    const parseQueryParam = (param: any): string => {
      if (Array.isArray(param)) {
        return param[0] ? String(param[0]) : "";
      }
      return param ? String(param) : "";
    };
    const limit = parseQueryParam(req.query.limit);
    const offset = parseQueryParam(req.query.offset);

    const { limitNumber, offsetNumber } =
      this.paginationUtils.validarLimitOffset(limit, offset);

    const nome = req.query.nome as string;
    const sigla = req.query.sigla as string;
    const ativoParam = parseQueryParam(req.query.ativo);
    const ativo = ativoParam ? ativoParam === "true" : undefined;

    const dto: ListarClientesInputDto = {
      nome,
      sigla,
      ativo,
      sortDirection: (req.query.sortDirection as string)?.toUpperCase(),
      sortField: req.query.sortField as string,
      limit: limitNumber,
      offset: offsetNumber,
    };

    const pagina: PaginacaoDto = await this.listarClientes.execute(dto);

    pagina.data = pagina.data.map((clienteDto) =>
      ClienteOutputMapper.toOutput(clienteDto),
    );

    return res.status(200).send(pagina);
  }
// --- use-case: ListarClientes.execute ---
{
    const pagina: PaginacaoDto =
      await this.clientesRep.listarTodosOsClientesPaginado(dto);

    return pagina;
  }
// --- repository: ClientesRepositorio.listarTodosOsClientesPaginado ---
{
    const { ativo, nome, sigla, limit, offset } = dto;

    // Validar sortField contra whitelist (proteção SQL injection)
    const allowedSortFields = ["nome", "sigla", "createdAt"];
    const sortField =
      dto.sortField && allowedSortFields.includes(dto.sortField)
        ? dto.sortField
        : "nome";

    const sortDirection = this.sanitizeSortDirection(dto.sortDirection);

    const where: any = {};
    if (nome && nome.trim() !== "") {
      where.nome = { [Op.iLike]: `%${nome.trim()}%` };
    }
    if (sigla && sigla.trim() !== "") {
      where.sigla = { [Op.iLike]: `%${sigla.trim()}%` };
    }
    if (ativo !== undefined) {
      where.ativo = ativo;
    }

    try {
      const { rows: clientesModelo, count: total } =
        await ClienteModelo.findAndCountAll({
          where,
          order: [[sortField, sortDirection]],
          limit: dto.limit,
          offset: dto.offset,
        });

      const clientes: ClienteDto[] = [];
      for (const clienteModelo of clientesModelo) {
        const gestores = await this.buscaGestores(clienteModelo.id);
        clientes.push(
          ClientePersistenceMapper.fromModel(clienteModelo, gestores),
        );
      }

      const pagina: PaginacaoDto = {
        data: clientes,
        pagination: {
          limit,
          offset,
          size: total,
        },
      };

      return pagina;
    } catch (error) {
      console.error("Erro em listarTodosOsClientesPaginado:", error);
      throw error;
    }
  }

