{
    const idConta = request.body?.idConta;
    const otp = request.body?.otp;

    if (typeof idConta !== "string" || !idConta.trim()) {
      throw new AppError("Parâmetro 'idConta' é obrigatório.", {
        code: ErrorCode.PARAM_INVALIDO,
        isOperational: false,
        meta: {
          param: "idConta",
          value: idConta,
        },
      });
    }

    if (typeof otp !== "string" || !otp.trim()) {
      throw new AppError("Parâmetro 'otp' é obrigatório.", {
        code: ErrorCode.PARAM_INVALIDO,
        isOperational: false,
        meta: {
          param: "otp",
          value: otp,
        },
      });
    }

    const authorization = request.headers.authorization;

    let token: string | undefined = undefined;
    if (authorization) {
      token = authorization.split(" ")[1].trim();
    }

    const resposta = await this.autenticarContaPessoa.autenticar(
      idConta,
      otp,
      token,
    );

    const cookieConfig = buildHttpOnlyCookieOptions(5 * 60 * 1000); // default = 5min

    response.cookie(AUTH_COOKIE_NAME, resposta.token, cookieConfig);

    response.cookie(
      CHALLENGE_COOKIE_NAME,
      resposta.registrationOptions.challenge,
      cookieConfig,
    );

    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { token: _token, ...output } = resposta;

    return response.status(200).send(output);
  }

