          grupoModelo,
          grupo.requisitantes,
          perfilRequisitante.id,
          t,
        );
      }

      await t.commit();

      // Buscar o grupo alterado para incluir os relacionamentos
      const grupoAlterado = await this.buscarGrupoPorId(grupoModelo.id);
      return grupoAlterado;
    } catch (error) {
      await t.rollback();
      throw error;
    }
  }

