// --- use-case: ListarGruposGestorOuRequisitante.execute ---
{
    // Validar GESTOR logado
    const gestorDto = await this.contasRep.buscarGestor(dto.idUsuarioLogado);

    if (!gestorDto && !dto.rolesUsuarioLogado.includes("ADMINISTRADOR")) {
      throw new AppError(
        "Usuário não autorizado ou não possui perfil ativo para esta funcionalidade.",
        {
          code: ErrorCode.USUARIO_NAO_AUTORIZADO,
          isOperational: false,
          meta: {
            user: { id: dto.idUsuarioLogado },
          },
        },
      );
    }

    const grupos: GrupoResumoOutput[] = [];

    /* Se o GESTOR for ADMINISTRADOR,
     * Deduzir idCliente a partir da conta do requisitante
     */
    if (
      dto.rolesUsuarioLogado.includes("ADMINISTRADOR") &&
      dto.idRequisitante
    ) {
      // Recuperar o requisitante
      const requisitanteDto = await this.contasRep.buscarContaPorId(
        dto.idRequisitante,
      );
      if (!requisitanteDto) {
        throw new AppError("Conta não encontrada.", {
          code: ErrorCode.ENTIDADE_NAO_ENCONTRADA,
          isOperational: false,
          meta: {
            entity: "CONTA",
            queryParams: { id: dto.idRequisitante },
          },
        });
      }

      const idCliente = requisitanteDto?.idCliente;
      grupos.push(
        ...(await this.gruposRep.buscarGruposResumidoPorIdCliente(
          idCliente!,
          dto.nome,
        )),
      );
    } else {
      grupos.push(
        ...(await this.gruposRep.buscarGruposResumidoCombinados(dto)),
      );
    }

    return grupos;
  }
// --- repository: ContasRepositorio.buscarGestor ---
{
    const query = `
    SELECT 
      c.id,
      c.id_cliente AS "idCliente",
      c.nome,
      c.codigo,
      c.tipo_codigo AS "tipoCodigo",
      c.tipo_conta AS "tipoConta",
      c.email,
      c.celular,
      c.tentativas_acesso_invalido AS "tentativasAcessoInvalido",
      c.timestamp_codigo_acesso AS "timestampCodigoAcesso",
      c.created_at AS "createdAt",
      c.updated_at AS "updatedAt",
      c.deleted_at AS "deletedAt",
      p.id AS "perfis.id",
      p.nome AS "perfis.nome",
      cp.ativo AS "perfis.contas-perfis.ativo",
      cp.id AS "contaPerfilId",
      COALESCE(
        (
          SELECT json_agg(
            json_build_object(
              'id', g.id,
              'nome', g.nome,
              'ativo', g.ativo
            ) ORDER BY g.id
          )
          FROM controlador."contas-perfis-grupos" cpg
          JOIN controlador.grupos g ON cpg.id_grupo = g.id AND g.deleted_at IS NULL
          WHERE cpg.id_conta_perfil = cp.id
          AND cpg.deleted_at IS NULL
        ),
        '[]'::json
      ) AS "perfis.grupos"
    FROM controlador.contas c
    INNER JOIN controlador."contas-perfis" cp 
      ON c.id = cp.id_conta 
      AND cp.deleted_at IS NULL
    INNER JOIN controlador.perfis p 
      ON cp.id_perfil = p.id
    WHERE 
      c.deleted_at IS NULL
      AND c.id = :id
      ${idCliente !== undefined ? "AND c.id_cliente = :idCliente" : ""}
      AND p.nome = 'GESTOR'
    ORDER BY c.id
  `;

    const replacements: Record<string, unknown> = { id };
    if (idCliente !== undefined) {
      replacements.idCliente = idCliente;
    }

    try {
      const results: any[] = await sequelize.query(query, {
        replacements,
        type: sequelize.QueryTypes.SELECT,
      });

      if (results.length === 0) {
        return null;
      }

      const contasAgrupadas = new Map<string, any>();

      for (const row of results) {
        const contaId = row.id;

        if (!contasAgrupadas.has(contaId)) {
          contasAgrupadas.set(contaId, {
            ...row,
            grupos: [],
            perfis: [],
          });
        }

        const conta = contasAgrupadas.get(contaId);

        const perfilComGrupos = {
          id: row["perfis.id"],
          nome: row["perfis.nome"],
          ativo: row["perfis.contas-perfis.ativo"],
          grupos: row["perfis.grupos"] || [],
        };

        conta.perfis.push(perfilComGrupos);
      }

      const contasModelo = Array.from(contasAgrupadas.values());
      const contaUnica = contasModelo[0];

      return ContaPersistenceMapper.fromModel(
        contaUnica,
        TipoPerfil.GESTOR,
      ) as ContaDto;
    } catch (error) {
      console.error("Erro em buscarGestor:", error);
      throw error;
    }
  }
